(() => {
  const selector = '#tab-arcsine-comparison';
  const root = document.querySelector(selector);
  if (!root) return;
  const tablist = root.querySelector('[role=tablist]');
  if (!tablist) return;
  const links = [...tablist.querySelectorAll('button[role=tab][data-tab]')];
  tablist.setAttribute('aria-label', '统计量比较');
  links.forEach((link, i) => {
    const panel = document.getElementById(link.dataset.tab);
    if (!panel) return;
    link.id = `arcsine-comparison-label-${i}`;
    link.setAttribute('aria-controls', panel.id);
    panel.setAttribute('role', 'tabpanel');
    panel.setAttribute('aria-labelledby', link.id);
  });
  if (window.arcsineReadingTabsReady) return;
  window.arcsineReadingTabsReady = true;
  document.addEventListener('keydown', event => {
    const link = event.target.closest(`${selector} button[role=tab][data-tab]`);
    if (!link) return;
    const options = [...link.closest('[role=tablist]').querySelectorAll('button[role=tab]')];
    let next;
    if (event.key === 'ArrowRight') next = (options.indexOf(link) + 1) % options.length;
    else if (event.key === 'ArrowLeft') next = (options.indexOf(link) - 1 + options.length) % options.length;
    else if (event.key === 'Home') next = 0;
    else if (event.key === 'End') next = options.length - 1;
    else if (event.key === ' ' || event.key === 'Enter') next = options.indexOf(link);
    if (next === undefined) return;
    event.preventDefault(); options[next].focus(); options[next].click();
  });
})();




